window.ROLES={"qc":{"label":"QA / QC","emoji":"🔍","scenarios":[{"k":"r_qc_ng","l":"Báo lỗi cho tổ trưởng","s":"You are a line leader. I am QC and I found a defect trend on your line this morning. Ask what the defect is, how many pieces are affected and what you should do now."},{"k":"r_qc_customer","l":"Nghe khách báo lỗi","s":"You are a foreign customer's quality engineer. You call about bad parts you received. Ask about the lot, the quantity and when we will reply."},{"k":"r_qc_fai","l":"Duyệt hàng đầu","s":"You are a production engineer. You need QC approval for the first article so the line can start. Ask me for the result and push a little because you are in a hurry."},{"k":"r_qc_audit","l":"Trả lời auditor","s":"You are an auditor checking our inspection process. Ask about sampling, records and what happens to NG parts."}],"dialogues":[{"them":"Can we ship Lot 18 today?","opts":[{"t":"Not yet. We found two scratches in the samples, so we're checking 100 percent. I'll tell you by 4 p.m.","good":true,"fb":"Trả lời + lý do + mốc thời gian."},{"t":"Maybe can, maybe cannot.","good":false,"fb":"Mơ hồ, thiếu chủ ngữ — bộ phận khác cần câu trả lời rõ."},{"t":"You always want to ship fast.","good":false,"fb":"Trách móc người hỏi thay vì trả lời."}]},{"them":"What's the defect rate this week?","opts":[{"t":"Defect rate is down little.","good":false,"fb":"Thiếu con số và thiếu 'a' ('down a little')."},{"t":"It's 1.2 percent, down from 1.8 last week. Scratches are still the top defect.","good":true,"fb":"Con số + so sánh + lỗi chính."},{"t":"I not calculate yet.","good":false,"fb":"Sai ngữ pháp: 'I haven't calculated it yet.'"}]},{"them":"The line leader says the part is OK. Why did you reject it?","opts":[{"t":"Because I am QC, I decide.","good":false,"fb":"Dùng quyền thay vì dữ liệu — dễ gây mâu thuẫn."},{"t":"The line leader is wrong always.","good":false,"fb":"Sai trật tự từ ('always wrong') và công kích cá nhân."},{"t":"The height is 10.12 millimetres, and the spec is 10.00 plus or minus 0.05. I can show you the data.","good":true,"fb":"Căn cứ bằng số đo và tiêu chuẩn, bình tĩnh."}]},{"them":"Did you check the first article?","opts":[{"t":"Yes. All dimensions are OK, and the appearance is fine. You can start mass production.","good":true,"fb":"Kết quả + cho phép bước tiếp theo."},{"t":"Yes, I checked it tomorrow.","good":false,"fb":"Sai thời gian: đã kiểm tra thì dùng 'this morning', không phải 'tomorrow'."},{"t":"First article checking.","good":false,"fb":"Thiếu chủ ngữ/động từ — không rõ đã xong chưa."}]},{"them":"How do you know which lot has the problem?","opts":[{"t":"We know by feeling.","good":false,"fb":"Không có căn cứ — QC phải truy vết bằng dữ liệu."},{"t":"We traced it by the date code on the label. All the bad pieces are from the night shift on May 3.","good":true,"fb":"Cách truy vết + kết quả cụ thể."},{"t":"Lot is on the label.","good":false,"fb":"Thiếu mạo từ và chưa trả lời lô nào có vấn đề."}]},{"them":"Can you send me the inspection data?","opts":[{"t":"OK, I send.","good":false,"fb":"Thiếu 'will' và 'it': 'OK, I'll send it.'"},{"t":"Data is secret.","good":false,"fb":"Cộc lốc và không hợp lý với người cần dữ liệu để xử lý."},{"t":"Sure. I'll email you the spreadsheet with all the measurements in ten minutes.","good":true,"fb":"Đồng ý + hình thức gửi + thời gian."}]}]},"engineer":{"label":"Kỹ sư sản xuất · Bảo trì","emoji":"🔧","scenarios":[{"k":"r_en_down","l":"Báo máy dừng cho quản lý","s":"You are the production manager. I am the maintenance engineer. A machine stopped 30 minutes ago. Ask about the cause, the repair time and the spare parts."},{"k":"r_en_expert","l":"Làm việc với chuyên gia Nhật","s":"You are a Japanese engineer who wants to change a machine setting. I need to understand your reason and the risk. Speak simply and answer my questions."},{"k":"r_en_trial","l":"Báo kết quả chạy thử","s":"You are my manager. I did a trial run with a new jig. Ask about the cycle time, the quality result and whether we can use it on all lines."},{"k":"r_en_vendor","l":"Gọi hãng máy hỗ trợ","s":"You are a service engineer from a foreign machine maker. I call because our machine shows an error code. Ask me for details and give simple steps to check."}],"dialogues":[{"them":"The press is making a strange noise. What's wrong?","opts":[{"t":"Is normal, old machine.","good":false,"fb":"Thiếu 'It' và bỏ qua dấu hiệu bất thường."},{"t":"I think the bearing is worn. Let's stop the press now so I can check it safely.","good":true,"fb":"Nhận định có căn cứ + ưu tiên an toàn."},{"t":"I don't know, ask maintenance.","good":false,"fb":"Đùn đẩy — kỹ sư nên kiểm tra hoặc cùng phối hợp."}]},{"them":"When will Machine 2 be ready?","opts":[{"t":"It ready afternoon.","good":false,"fb":"Thiếu 'will be … in the' và không có giờ cụ thể."},{"t":"When the part come.","good":false,"fb":"Câu cụt, thiếu 's' ('comes') và không có mốc thời gian."},{"t":"By 2 p.m. We're replacing the motor now, and then we'll do a trial run.","good":true,"fb":"Giờ cụ thể + đang làm gì + bước kiểm tra."}]},{"them":"Why do we need to stop the line on Saturday?","opts":[{"t":"For preventive maintenance. It stops breakdowns during the week, so we lose less time overall.","good":true,"fb":"Lý do + lợi ích rõ ràng."},{"t":"Because the plan says.","good":false,"fb":"Câu thiếu ('the plan says so') và chưa giải thích lợi ích — người hỏi muốn biết 'để làm gì'."},{"t":"Saturday is maintenance day, that's all.","good":false,"fb":"Cộc lốc, không thuyết phục."}]},{"them":"Can the new jig reduce cycle time?","opts":[{"t":"Yes, it very fast.","good":false,"fb":"Thiếu động từ ('it's much faster') và không có số liệu."},{"t":"Yes. In the trial run, it went down from 48 to 41 seconds, with no defects.","good":true,"fb":"Kết quả chạy thử bằng số + chất lượng."},{"t":"I hope it can reduce.","good":false,"fb":"Chỉ là mong đợi, không có dữ liệu."}]},{"them":"The alarm code is E-45. What does it mean?","opts":[{"t":"E-45 is alarm.","good":false,"fb":"Nhắc lại câu hỏi, không giải thích gì."},{"t":"Mean machine broken.","good":false,"fb":"Thiếu chủ ngữ/động từ, kết luận vội."},{"t":"It means low air pressure. Please check the air valve behind the machine.","good":true,"fb":"Giải thích + hướng dẫn kiểm tra cụ thể."}]},{"them":"Did you change the machine setting yesterday?","opts":[{"t":"Yes, I changed the speed from 80 to 70 percent. I wrote it in the change record.","good":true,"fb":"Xác nhận + thông số cụ thể + có ghi hồ sơ."},{"t":"Yes, I change a little.","good":false,"fb":"Sai thì ('changed') và không nói thông số."},{"t":"No, maybe someone else.","good":false,"fb":"Né tránh, không kiểm tra hồ sơ."}]}]},"leader":{"label":"Tổ trưởng · Giám sát","emoji":"👷","scenarios":[{"k":"r_ld_meeting","l":"Họp đầu ca","s":"You are a foreign production manager joining my morning line meeting. Ask about today's target, the number of workers and today's safety point."},{"k":"r_ld_behind","l":"Báo chậm tiến độ","s":"You are the production manager. My line is 150 units behind target at noon. Ask why and what my plan is to recover."},{"k":"r_ld_worker","l":"Nhắc nhở công nhân","s":"You are an operator who is not wearing safety glasses. I am your line leader. At first give an excuse, then agree to follow the rule."},{"k":"r_ld_kaizen","l":"Đề xuất cải tiến","s":"You are the factory manager. I have a kaizen idea for my line. Ask about the problem, the cost and the expected result."}],"dialogues":[{"them":"How many workers do you have today?","opts":[{"t":"Today have 28 people.","good":false,"fb":"Thiếu chủ ngữ: 'We have 28 people today.'"},{"t":"Not enough, very difficult.","good":false,"fb":"Than phiền, không có số liệu hay giải pháp."},{"t":"Twenty-eight out of thirty. Two are on sick leave, so I've moved one person from Line 4.","good":true,"fb":"Số liệu + lý do + cách xử lý."}]},{"them":"Your line is behind target. What happened?","opts":[{"t":"We lost 40 minutes on the changeover this morning. We'll recover it with 30 minutes of overtime.","good":true,"fb":"Nguyên nhân + phương án bù sản lượng."},{"t":"Workers is slow today.","good":false,"fb":"Sai chia động từ ('are') và đổ lỗi cho công nhân."},{"t":"I don't know why.","good":false,"fb":"Tổ trưởng cần nắm và báo được nguyên nhân."}]},{"them":"Why isn't this worker wearing gloves?","opts":[{"t":"He forget, not my fault.","good":false,"fb":"Sai thì ('forgot') và đổ lỗi."},{"t":"Sorry, I'll talk to him now. I'll also check PPE at the start of every shift.","good":true,"fb":"Nhận trách nhiệm + xử lý ngay + phòng ngừa."},{"t":"Gloves are finish.","good":false,"fb":"Sai ngữ pháp ('We've run out of gloves') — nếu hết thì phải báo ngay."}]},{"them":"Can your line make 200 more units today?","opts":[{"t":"OK, try my best.","good":false,"fb":"Hứa chung chung, thiếu chủ ngữ, không có con số."},{"t":"No, impossible.","good":false,"fb":"Từ chối ngay, không đưa phương án."},{"t":"We can make 120 more with one hour of overtime. For 200, I'd need two more workers.","good":true,"fb":"Đưa con số khả thi + điều kiện."}]},{"them":"What's today's safety point?","opts":[{"t":"Keep the walkway clear. Yesterday a trolley blocked the emergency exit.","good":true,"fb":"Nhắc cụ thể + ví dụ thực tế."},{"t":"Safety is important.","good":false,"fb":"Quá chung chung, không có điểm cụ thể."},{"t":"Same yesterday.","good":false,"fb":"Thiếu 'as' ('Same as yesterday') và không nêu nội dung."}]},{"them":"Who will cover Station 3 during lunch?","opts":[{"t":"Somebody will.","good":false,"fb":"Mơ hồ — tổ trưởng phải phân công rõ."},{"t":"Nga will cover it. She's certified for Station 3.","good":true,"fb":"Người cụ thể + lý do có năng lực."},{"t":"Nga cover.","good":false,"fb":"Thiếu 'will': 'Nga will cover it.'"}]}]},"planner":{"label":"Kế hoạch · Kho · Mua hàng","emoji":"📦","scenarios":[{"k":"r_pl_change","l":"Khách tăng đơn hàng","s":"You are a foreign customer. You want to increase next week's order by 30 percent. Ask if we can deliver on time and what we need from you."},{"k":"r_pl_supplier","l":"Hối nhà cung cấp","s":"You are a supplier's salesperson. Your delivery of materials is three days late. I call to ask for the new date. Apologize and give a reason."},{"k":"r_pl_short","l":"Báo thiếu vật tư","s":"You are the production manager. I report a shortage of a part for tomorrow's plan. Ask how serious it is and what my plan is."},{"k":"r_pl_ship","l":"Xác nhận xuất hàng","s":"You are a logistics coordinator for a foreign customer. Ask me to confirm the shipment date, the quantity and the documents."}],"dialogues":[{"them":"Can you move our order to next Monday?","opts":[{"t":"Let me check our capacity and materials. I'll confirm by 5 p.m. today.","good":true,"fb":"Không hứa vội + hẹn giờ trả lời."},{"t":"Yes, sure, no problem.","good":false,"fb":"Hứa ngay khi chưa kiểm tra công suất."},{"t":"Cannot, plan is fixed.","good":false,"fb":"Cộc, thiếu chủ ngữ; nên kiểm tra trước khi trả lời."}]},{"them":"Why is the delivery late?","opts":[{"t":"Because supplier fault.","good":false,"fb":"Thiếu động từ, chỉ đổ lỗi, không có ngày giao mới."},{"t":"Our supplier delivered the resin three days late. We're running overtime, and the goods will ship on Thursday.","good":true,"fb":"Nguyên nhân + đang làm gì + ngày giao mới."},{"t":"It was late because it is late.","good":false,"fb":"Không giải thích gì."}]},{"them":"How much stock do we have for Part A?","opts":[{"t":"Stock have many.","good":false,"fb":"Sai ngữ pháp và không có con số."},{"t":"I think a lot, I will check maybe.","good":false,"fb":"Thiếu chắc chắn; nên kiểm tra trước rồi trả lời."},{"t":"3,200 pieces. That's enough for about four days of production.","good":true,"fb":"Con số + quy đổi ra số ngày dùng."}]},{"them":"The supplier says the material will be one week late.","opts":[{"t":"Then let's ask them to send part of it by air. I'll also check if another supplier can help.","good":true,"fb":"Đưa hai phương án cụ thể."},{"t":"OK, we wait.","good":false,"fb":"Bị động — trễ một tuần có thể làm dừng chuyền."},{"t":"Supplier is bad, change now.","good":false,"fb":"Cảm tính, thiếu mạo từ; đổi nhà cung cấp cần đánh giá."}]},{"them":"Is the shipment ready?","opts":[{"t":"Ready already all.","good":false,"fb":"Sai trật tự từ: 'Everything is ready.'"},{"t":"Yes. 4,800 units are packed, and the invoice and packing list are ready.","good":true,"fb":"Xác nhận + số lượng + chứng từ."},{"t":"Yes, it was ready next week.","good":false,"fb":"Sai thì: không dùng 'was' với 'next week'."}]},{"them":"Why is the system stock different from the shelf?","opts":[{"t":"System is wrong, not us.","good":false,"fb":"Đổ lỗi cho hệ thống, thiếu mạo từ."},{"t":"Different a little only.","good":false,"fb":"Sai trật tự và xem nhẹ chênh lệch tồn kho."},{"t":"Some parts were used without a record. We'll do a stock count today and correct the system.","good":true,"fb":"Nguyên nhân + hành động cụ thể."}]}]}};
